INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('62d23419-0510-4f35-9098-8111d5a7a3c8', '150f78d3-019b-40c0-962e-a83576309ea5', 2, 'A Ferida Aberta', NULL, '{"intro": "A vulnerabilidade \u00e9 a porta de entrada para a gra\u00e7a.", "prayer": "Mostre a Ele o seu cora\u00e7\u00e3o partido.", "practice": "N\u00e3o esconda a sua tristeza hoje; sinta-a diante dEle.", "reflection": "\u00c9 pela rachadura no cora\u00e7\u00e3o que a luz entra.", "journal_prompt": "O que voc\u00ea est\u00e1 tentando proteger com tanto esfor\u00e7o?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;